"""Private Timeline revision operations used by the public remote facade."""

from __future__ import annotations

import uuid
from typing import TYPE_CHECKING, Any, Mapping

from .contracts import DomainResult, ErrorObject


class _RemoteTimelineRevisionMixin:
    """Keep canonical revision reads and ledger operations off ``remote.py``.

    The mixin deliberately relies on ``_RemoteFamily`` for the typed transport
    and on ``RemoteTimelines`` for timeline scope resolution.  It therefore
    moves no authority or transport policy; it only keeps the cohesive
    revision-operation facade together in a private neighboring module.
    """

    if TYPE_CHECKING:
        def _resolve_timeline(self, project: Any, ref: Any) -> DomainResult[Any]: ...

        def _typed(
            self, operation: str, *args: Any, key: str | None = None, **kwargs: Any,
        ) -> DomainResult[Any]: ...

    def open_bundle(self, project, ref, *, revision_id=None, publication_id=None):
        """Read one complete, read-only authoring bundle (parent → shots → internal timelines).

        The same closure ``timeline_document.py checkout`` writes, pinned to the
        current head or to ``revision_id``. ``timelines show`` builds its cut
        table from it and ``timelines diff`` compares two of them. Nothing is
        written. Returns ``{bundle, project_id, timeline_id, revision_id,
        is_current_head}``.
        """
        from astrid.core.timeline.authoring_bundle import (
            AuthoringBundleError,
            open_authoring_bundle,
        )
        from astrid.sdk.timeline.commit import (
            INTERNAL_IMAGE_FIELDS,
            PARENT_IMAGE_FIELDS,
            SHOT_IMAGE_FIELDS,
            _json,
            bundle_from_document,
        )

        opened = self.open_composition(project, ref, revision_id=revision_id, limit=1)
        if not opened.ok or not isinstance(opened.data, Mapping):
            return opened
        native = opened.data.get("native_inspection") if isinstance(opened.data.get("native_inspection"), Mapping) else {}
        summary = opened.data.get("summary") if isinstance(opened.data.get("summary"), Mapping) else {}
        project_id = native.get("project_id")
        timeline_id = native.get("timeline_id")
        head = summary.get("head_revision_id") or native.get("head_revision_id")
        revision = revision_id or summary.get("revision_id") or head
        if not all(isinstance(value, str) and value for value in (project_id, timeline_id, revision)):
            return DomainResult.failure(ErrorObject(
                "protocol_error",
                "timeline inspection did not return a project id, timeline id and revision",
                {"project": str(project), "timeline": str(ref)},
            ))
        if publication_id is not None and (not revision_id or not isinstance(publication_id, str) or not publication_id):
            return DomainResult.failure(ErrorObject(
                "protocol_error", "source hydration requires the exact original revision/publication pair", {}
            ))
        parent = self._typed("get_project_parent_composition_revision", project_id, timeline_id, revision)
        if not parent.ok or not isinstance(parent.data, Mapping):
            return parent
        if any(parent.data.get(key) != value for key, value in {
            "project_id": project_id, "timeline_id": timeline_id, "revision_id": revision,
        }.items()):
            return DomainResult.failure(ErrorObject(
                "integrity_error", "parent revision response does not match its exact scope or pin",
                {"project_id": project_id, "timeline_id": timeline_id, "revision_id": revision},
            ))
        payload = parent.data.get("payload") if isinstance(parent.data.get("payload"), Mapping) else {}
        owner_by_revision: dict[str, str] = {}
        manifest = parent.data.get("dependency_manifest")
        manifest_rows = manifest.get("internal_timelines") if isinstance(manifest, Mapping) else None
        if isinstance(manifest_rows, list):
            for row in manifest_rows:
                if not isinstance(row, Mapping):
                    return DomainResult.failure(ErrorObject(
                        "integrity_error", "canonical internal timeline pin is invalid", {}
                    ))
                child_revision, owner = row.get("revision_id"), row.get("timeline_id")
                if not isinstance(child_revision, str) or not isinstance(owner, str) or not owner:
                    return DomainResult.failure(ErrorObject(
                        "integrity_error", "canonical internal timeline pin has no exact owner", {}
                    ))
                previous = owner_by_revision.setdefault(child_revision, owner)
                if previous != owner:
                    return DomainResult.failure(ErrorObject(
                        "integrity_error", "canonical internal revision has conflicting owners",
                        {"revision_id": child_revision},
                    ))
        shots: dict[str, Any] = {}
        internals: dict[str, Any] = {}
        for occurrence in payload.get("occurrences") or []:
            if not isinstance(occurrence, Mapping):
                continue
            shot_revision = occurrence.get("shot_revision_id") or occurrence.get("revision_id")
            if shot_revision not in shots:
                shot = self._typed("get_project_shot_revision", project_id, occurrence.get("shot_id"), shot_revision)
                if not shot.ok or not isinstance(shot.data, Mapping):
                    return shot
                if (shot.data.get("project_id"), shot.data.get("shot_id"), shot.data.get("revision_id")) != (
                    project_id, occurrence.get("shot_id"), shot_revision,
                ):
                    return DomainResult.failure(ErrorObject(
                        "integrity_error",
                        "shot revision response does not match its exact scope or pin",
                        {"project_id": project_id, "shot_id": occurrence.get("shot_id"),
                         "revision_id": shot_revision},
                    ))
                shots[shot_revision] = shot.data
            shot_data = shots[shot_revision]
            shot_payload = shot_data.get("payload") if isinstance(shot_data.get("payload"), Mapping) else {}
            internal_revision = shot_data.get("internal_timeline_revision_id") or shot_payload.get("internal_timeline_revision_id")
            if internal_revision not in internals:
                internal_owner = owner_by_revision.get(internal_revision)
                if not isinstance(internal_owner, str) or not internal_owner:
                    return DomainResult.failure(ErrorObject(
                        "integrity_error",
                        "pinned internal revision has no exact owner timeline",
                        {"revision_id": internal_revision},
                    ))
                internal = self._typed("get_project_timeline_revision", project_id, internal_owner, internal_revision)
                if not internal.ok or not isinstance(internal.data, Mapping):
                    return internal
                if (internal.data.get("project_id"), internal.data.get("timeline_id"),
                        internal.data.get("revision_id")) != (project_id, internal_owner, internal_revision):
                    return DomainResult.failure(ErrorObject(
                        "integrity_error",
                        "internal revision response does not match its exact owner or pin",
                        {"project_id": project_id, "timeline_id": internal_owner, "revision_id": internal_revision},
                    ))
                internals[internal_revision] = internal.data
        try:
            # Runtime revision reads carry outer storage/read-envelope fields
            # that are not part of a canonical immutable image.  Keep those
            # raw rows available to callers, but project the source graph onto
            # the existing canonical fieldsets before opening the bundle.
            parent_image = {
                **{key: parent.data[key] for key in PARENT_IMAGE_FIELDS},
                "project_id": project_id,
                "timeline_id": timeline_id,
            }
            shot_images = [
                {
                    **{key: row[key] for key in SHOT_IMAGE_FIELDS},
                    "project_id": row.get("project_id", project_id),
                }
                for row in shots.values()
            ]
            internal_images = [
                {
                    **{key: row[key] for key in INTERNAL_IMAGE_FIELDS},
                    "project_id": row.get("project_id", project_id),
                }
                for row in internals.values()
            ]
            bundle = open_authoring_bundle(
                parent_image,
                shot_revisions=shot_images,
                internal_timeline_revisions=internal_images,
            )
            if publication_id is not None:
                # Bind the immutable read to the original publication, even if
                # another writer has advanced the head. Never infer retained pins.
                cursor, seen = None, set()
                while True:
                    page = self.history(project_id, timeline_id, cursor=cursor, limit=100)
                    if not page.ok:
                        return page
                    entry = next((row for row in page.data["items"]
                                  if row["publication_id"] == publication_id), None)
                    if entry is not None:
                        if entry["revision_id"] != revision or entry["receipt"]["receipt_id"] != publication_id:
                            raise AuthoringBundleError("original revision/publication pair changed")
                        break
                    cursor = page.data.get("next_cursor")
                    if cursor is None or cursor in seen:
                        raise AuthoringBundleError("original publication is unavailable")
                    seen.add(cursor)
                document = entry["receipt"]["result"].get("canonical_document")
                if document is None:
                    # Bootstrap/legacy receipts need the manifest retained by
                    # Runtime's verified immutable parent read, not a rebuilt one.
                    document = {
                        "schema_version": 1, "project_id": project_id, "timeline_id": timeline_id,
                        "parent_revision": {key: parent.data[key] for key in PARENT_IMAGE_FIELDS},
                        "shot_revisions": sorted(
                            ({key: row[key] for key in SHOT_IMAGE_FIELDS} for row in shots.values()),
                            key=lambda row: (row["shot_id"], row["revision_id"])),
                        "internal_timeline_revisions": sorted(
                            ({key: row[key] for key in INTERNAL_IMAGE_FIELDS} for row in internals.values()),
                            key=lambda row: (row["timeline_id"], row["revision_id"])),
                        "dependency_manifest": parent.data["dependency_manifest"],
                    }
                hydrated = bundle_from_document(document)
                source = hydrated["source_mapping"].pop("_runtime_document")
                if _json(hydrated) != _json(bundle) or ("dependency_manifest" in parent.data
                        and _json(parent.data["dependency_manifest"]) != _json(source["dependency_manifest"])):
                    raise AuthoringBundleError("canonical document differs from the original closure read")
                bundle["source_mapping"]["_runtime_document"] = source
                bundle["base_parent"]["publication_id"] = publication_id
        except (AuthoringBundleError, KeyError, TypeError) as exc:
            return DomainResult.failure(ErrorObject(
                "protocol_error", f"could not open the timeline closure: {exc}",
                {"timeline": timeline_id, "revision_id": revision},
            ))
        return DomainResult.success({
            "bundle": bundle,
            "project_id": project_id,
            "timeline_id": timeline_id,
            "revision_id": revision,
            "head_revision_id": head,
            "is_current_head": revision == head,
        })

    def commit(self, project, ref, body: Mapping[str, Any], *, idempotency_key=None):
        """Commit a scoped command batch without changing its request body."""
        key = idempotency_key or uuid.uuid4().hex
        resolved = self._resolve_timeline(project, ref)
        if not resolved.ok:
            return DomainResult.failure(resolved.error, idempotency_key=key)
        scope = resolved.data
        project_id = scope.get("project_id") if isinstance(scope, Mapping) else None
        timeline_id = scope.get("timeline_id") if isinstance(scope, Mapping) else None
        if not isinstance(project_id, str) or not project_id or not isinstance(timeline_id, str) or not timeline_id:
            return DomainResult.failure(
                ErrorObject("protocol_error", "timeline scope has no canonical project/timeline identity", {}),
                idempotency_key=key,
            )
        if not isinstance(body, Mapping) or body.get("project_id") != project_id or body.get("timeline_id") != timeline_id:
            return DomainResult.failure(
                ErrorObject(
                    "validation_error",
                    "commit body does not match the resolved timeline scope",
                    {"project_id": project_id, "timeline_id": timeline_id},
                ),
                idempotency_key=key,
            )
        return self._typed(
            "commit_timeline", project_id, timeline_id, body,
            key=key, idempotency_key=key,
        )

    def history(self, project, ref, *, cursor=None, limit=50):
        """Read scoped immutable commit history, including its exact head pair."""
        resolved = self._resolve_timeline(project, ref)
        if not resolved.ok:
            return resolved
        scope = resolved.data
        project_id = scope.get("project_id") if isinstance(scope, Mapping) else None
        timeline_id = scope.get("timeline_id") if isinstance(scope, Mapping) else None
        if not isinstance(project_id, str) or not project_id or not isinstance(timeline_id, str) or not timeline_id:
            return DomainResult.failure(
                ErrorObject("protocol_error", "timeline scope has no canonical project/timeline identity", {})
            )
        return self._typed(
            "list_timeline_commits", project_id, timeline_id,
            cursor=cursor, limit=limit,
        )

    def recover(self, project, ref, *, expected_version=None, version=None, idempotency_key=None):
        key = idempotency_key or uuid.uuid4().hex
        resolved = self._resolve_timeline(project, ref)
        if not resolved.ok or not isinstance(resolved.data, Mapping):
            return DomainResult.failure(resolved.error, idempotency_key=key)
        timeline_id = resolved.data.get("timeline_id")
        if not isinstance(timeline_id, str) or not timeline_id:
            return DomainResult.failure(
                ErrorObject("protocol_error", "timeline listing has no canonical identity", {}),
                idempotency_key=key,
            )
        try:
            value = resolved.data.get("version", resolved.data.get("config_version", 1))
            current_version = int(value)
            expected = int(expected_version) if expected_version is not None else current_version
            target = current_version if version is None else int(version)
        except (TypeError, ValueError):
            return DomainResult.failure(
                ErrorObject("protocol_error", "Runtime timeline listing has no valid version", {}),
                idempotency_key=key,
            )
        return self._typed(
            "recover_timeline",
            timeline_id,
            key=key,
            expected_version=expected,
            version=target,
            idempotency_key=key,
        )

"""Explicit transport adapter around the generated workspace client.

HTTP protocol encoding, authentication, and response decoding are delegated
to the generated ``astrid_runtime_client`` package from the runtime
contract. Endpoint and credential values are supplied by the caller.
"""

from __future__ import annotations

import errno
import ipaddress
import json
import os
import stat
from dataclasses import asdict, is_dataclass
from pathlib import Path
from typing import Any, Mapping
from urllib.parse import urlsplit

from astrid_runtime_client import WorkspaceClient as GeneratedWorkspaceClient
from astrid_runtime_client.contract_metadata import PROTOCOL, SCHEMA_DIGEST

from .pagination import page_pair, paged_rows

__all__ = [
    "GeneratedWorkspaceClient",
    "PROTOCOL",
    "SCHEMA_DIGEST",
    "WorkspaceClient",
    "WorkspaceClientError",
    "paged_rows",
    "resolve_runtime_connection",
]

_DOCUMENT_CONTENT_UNSET = object()

RECONFIGURE_ACTION = "run the Astrid install line again"


def _reconfigure(field: str, message: str) -> "WorkspaceClientError":
    return WorkspaceClientError(
        0,
        "reconfigure_required",
        message,
        {"field": field, "next_action": RECONFIGURE_ACTION},
    )


def _safe_local_path(value: str | Path, *, field: str) -> Path:
    """Return a regular local path, rejecting symlinked discovery inputs.

    Launcher result paths are security-sensitive: resolving a symlink before
    checking it would let a changed manifest or credential path silently point
    at an unrelated file.  Check the lexical path and every existing parent
    first, then let the caller check the file type/content.
    """
    path = Path(value).expanduser()
    if not path.is_absolute():
        path = Path.cwd() / path
    path = Path(path.absolute())
    current = path
    while True:
        try:
            if current.is_symlink():
                raise _reconfigure(field, f"{field} path must not be a symlink; {RECONFIGURE_ACTION}")
        except OSError as exc:
            raise _reconfigure(field, f"cannot inspect {field} path; {RECONFIGURE_ACTION}") from exc
        if current == current.parent:
            break
        current = current.parent
    return path


def validate_runtime_endpoint(endpoint: str) -> str:
    """Validate an explicit runtime URL without permitting network pivots."""
    value = str(endpoint).strip()
    try:
        parsed = urlsplit(value)
        hostname = parsed.hostname
        # Accessing port validates malformed values such as ``:not-a-port``.
        _ = parsed.port
    except ValueError as exc:
        raise _reconfigure("endpoint", f"runtime endpoint is malformed; {RECONFIGURE_ACTION}") from exc
    host = hostname.rstrip(".").lower() if hostname else ""
    is_loopback = host == "localhost"
    if host and not is_loopback:
        try:
            is_loopback = ipaddress.ip_address(host).is_loopback
        except ValueError:
            is_loopback = False
    if (
        parsed.scheme.lower() not in {"http", "https"}
        or not is_loopback
        or parsed.username is not None
        or parsed.password is not None
        or parsed.query
        or parsed.fragment
        or value.rstrip("/") in {"http:", "https:"}
    ):
        raise _reconfigure(
            "endpoint",
            "runtime endpoint must be an explicit loopback http(s) URL; " + RECONFIGURE_ACTION,
        )
    return value.rstrip("/")


class WorkspaceClientError(RuntimeError):
    def __init__(
        self,
        status: int,
        code: str,
        message: str,
        details: Mapping[str, Any] | None = None,
        *,
        request_id: str = "",
    ) -> None:
        super().__init__(message)
        self.status, self.code, self.message = status, code, message
        self.details = dict(details or {})
        self.request_id = request_id


def _read_credential(path: Path) -> str:
    # A target-bound worker may be allowed to open only this exact token file;
    # its parent directory is intentionally denied. Inspecting every parent
    # with lstat makes that narrow grant unusable. Linux can compare the
    # kernel-resolved descriptor path without inspecting those directories.
    # Other systems compare the canonical path and retained file identity.
    path = Path(path).expanduser()
    if not path.is_absolute():
        path = Path.cwd() / path
    if ".." in path.parts:
        raise _reconfigure("credential", f"credential path must not traverse a parent; {RECONFIGURE_ACTION}")
    try:
        nofollow = getattr(os, "O_NOFOLLOW", 0)
        if not nofollow:
            # Retain the older all-parent inspection policy on platforms that
            # cannot obtain a no-follow descriptor for the leaf.
            path = _safe_local_path(path, field="credential")
        descriptor = os.open(path, os.O_RDONLY | nofollow)
        with os.fdopen(descriptor, "r", encoding="utf-8") as handle:
            if not stat.S_ISREG(os.fstat(handle.fileno()).st_mode):
                raise _reconfigure("credential", f"runtime credential is not a regular file; {RECONFIGURE_ACTION}")
            if os.name == "posix" and Path("/proc/self/fd").is_dir():
                opened_path = os.readlink(f"/proc/self/fd/{handle.fileno()}")
            else:
                opened_path = str(path.resolve(strict=True))
                if not os.path.samestat(os.fstat(handle.fileno()), path.stat()):
                    opened_path = ""
            if not opened_path or opened_path != str(path):
                raise _reconfigure("credential", f"credential path must not contain a symlink; {RECONFIGURE_ACTION}")
            raw = handle.read().strip()
    except OSError as exc:
        if exc.errno == errno.ELOOP:
            raise _reconfigure("credential", f"credential path must not contain a symlink; {RECONFIGURE_ACTION}") from exc
        raise _reconfigure("credential", f"runtime credential is unavailable; {RECONFIGURE_ACTION}") from exc
    if not raw:
        raise _reconfigure("credential", f"runtime credential is empty; {RECONFIGURE_ACTION}")
    try:
        value = json.loads(raw)
    except json.JSONDecodeError:
        return raw
    token = value.get("token") if isinstance(value, dict) else None
    if not isinstance(token, str) or not token:
        raise _reconfigure("credential", f"runtime credential is invalid; {RECONFIGURE_ACTION}")
    return token


def resolve_runtime_connection(
    endpoint: str | None = None,
    credential: str | Path | None = None,
) -> tuple[str, str]:
    """Validate a runtime connection supplied by the caller or host boundary.

    Pack executors run in a host-created child process.  The host may provide
    the same explicit connection through ``ASTRID_RUNTIME_ENDPOINT`` and
    ``ASTRID_RUNTIME_CREDENTIAL``; this is still an explicit boundary, not
    runtime discovery.  A credential environment value is treated as an
    owner-only path when it names an existing file, otherwise as a bearer
    token already held by the host.
    """
    if endpoint is None:
        endpoint = os.environ.get("ASTRID_RUNTIME_ENDPOINT", "")
    if credential is None:
        raw_credential = os.environ.get("ASTRID_RUNTIME_CREDENTIAL", "").strip()
        credential = (
            Path(raw_credential)
            if raw_credential and Path(raw_credential).expanduser().is_file()
            else raw_credential
        )
    endpoint = validate_runtime_endpoint(endpoint)
    if not isinstance(credential, (str, Path)):
        raise _reconfigure("credential", f"runtime credential must be explicit and non-empty; {RECONFIGURE_ACTION}")
    if isinstance(credential, Path):
        token = _read_credential(Path(credential))
    else:
        token = str(credential).removeprefix("Bearer ").strip()
    if not token:
        raise _reconfigure("credential", f"runtime credential must be explicit and non-empty; {RECONFIGURE_ACTION}")
    return endpoint, token


class WorkspaceClient:
    """Small typed facade over the runtime's generated workspace client.

    This class deliberately contains no HTTP protocol code or local discovery.
    It translates only generated exceptions into Astrid's stable error type.
    """

    def __init__(self, endpoint: str, token: str):
        self.endpoint, self.token = resolve_runtime_connection(endpoint, token)
        self._generated = GeneratedWorkspaceClient(self.endpoint, self.token)
        # Populated after the explicit Astrid handshake.  On-demand local
        # Runtime work must use the authenticated actor as its executor.
        self.actor_id: str | None = None
        self._last_handshake: Any | None = None

    def _call_generated(self, operation: str, *args: Any, **kwargs: Any) -> Any:
        """Invoke one generated operation and normalize its typed value."""
        try:
            # Resolve exactly one method on demand.  The generated contract is
            # versioned independently of Astrid: a partial client used for a
            # narrow operation (for example ``settle_attempt``) must not fail
            # while constructing a map that eagerly looks up unrelated newer
            # operations such as ``health``.
            operations = {
                "health", "handshake", "doctor", "create_backup", "restore_backup",
                "export_realm", "tombstone_realm", "recover_realm", "purge_realm",
                "create_project", "get_project", "update_project", "list_projects",
                "select_project", "current_project", "create_timeline", "rename_timeline",
                "create_timeline_document", "update_timeline_document", "list_timelines",
                "get_timeline", "get_project_timeline", "list_timeline_history",
                "commit_timeline", "list_timeline_commits", "replace_timeline_clip",
                "get_project_verified_document", "get_project_verified_document_object",
                "diff_timeline", "archive_timeline",
                "recover_timeline", "list_project_shots", "create_project_shot",
                "inspect_timeline", "create_timeline_view",
                "get_project_shot", "update_project_shot", "archive_project_shot",
                "recover_project_shot", "add_shot_item", "remove_shot_item",
                "get_project_shot_revision", "get_project_timeline_revision",
                "get_project_parent_composition_revision",
                "publish_parent_composition",
                "replace_parent_composition_media",
                "promote_project_shot_candidate", "reorder_shot_items",
                "list_project_references", "create_project_reference",
                "list_project_shot_text_bindings", "set_project_shot_text_binding",
                "get_project_shot_text_binding", "set_project_shot_text_binding_by_id",
                "rebind_project_shot_text_binding",
                "get_project_reference", "update_project_reference", "archive_project_reference",
                "recover_project_reference", "associate_reference", "set_primary_reference",
                "link_references", "create_document", "list_documents", "get_document",
                "update_document", "ingest_object", "ingest_project_object",
                "get_preferences", "update_preferences",
                "import_project_media", "get_project_media_import",
                "list_project_objects", "get_project_object_location", "create_media_relation", "list_media_relations",
                "get_object", "head_object", "admit_task", "get_task", "list_project_tasks",
                "cancel_task", "retry_task", "cancel_run", "retry_run", "get_run",
                "list_project_runs", "list_run_events", "list_managed_outputs",
                "list_events",  # Includes the from_=latest polling cursor.
                "get_managed_output", "list_generations",
                "get_project_media_selection", "get_project_verified_media",
                "get_generation", "list_variants", "attach_variant_thumbnail",
                "get_source_frame_thumbnail", "ensure_source_frame_thumbnail",
                "mark_variant_viewed", "mark_generation_variants_viewed",
                "create_generation", "create_variant",
                "list_capabilities", "register_capability", "claim_task", "register_executor",
                "settle_attempt", "fail_attempt", "publish_timeline_render",
                "record_remote_activation", "control_remote_credential", "get_executor",
                "get_local_worker_generation", "relinquish_local_worker", "start_local_worker",
            }
            if operation not in operations:
                raise ValueError(f"unknown generated workspace operation: {operation!r}")
            try:
                generated = getattr(self._generated, operation)
            except AttributeError as exc:
                raise WorkspaceClientError(
                    503,
                    "not_ready",
                    f"generated Runtime client does not provide {operation!r}",
                    {
                        "reason": "runtime_unavailable",
                        "operation": operation,
                        "next_action": (
                            "install the Runtime generated client with Timeline M1 support"
                        ),
                    },
                ) from exc
            if not callable(generated):
                raise AttributeError(f"generated workspace operation is not callable: {operation!r}")
            value = generated(*args, **kwargs)
        except WorkspaceClientError:
            raise
        except Exception as exc:  # generated ApiError has stable fields
            raise WorkspaceClientError(
                int(getattr(exc, "status", 0)),
                str(getattr(exc, "code", "transport_error")),
                str(getattr(exc, "message", exc)),
                getattr(exc, "details", {}),
                request_id=str(getattr(exc, "request_id", "")),
            ) from exc
        def plain(item: Any) -> Any:
            if is_dataclass(item):
                return {key: plain(child) for key, child in asdict(item).items()}
            if isinstance(item, tuple):
                # Transport values are part of the JSON product surface;
                # never leave tuples in a DomainResult payload where the
                # canonical encoder would reject them.
                return [plain(child) for child in item]
            if isinstance(item, list):
                return [plain(child) for child in item]
            if isinstance(item, dict):
                return {key: plain(child) for key, child in item.items()}
            return item
        # The generated client carries committed mutation receipts as an
        # out-of-band ``MutationResult.receipt`` attribute on its resource
        # mapping. Preserve that attribute across the plain JSON conversion;
        # RemoteAstridClient._typed consumes the stable {data, receipt}
        # envelope and turns it into DomainResult.receipt.
        if hasattr(value, "receipt") and isinstance(value, dict):
            data = dict(value)
            # Some generated clients retain the wire receipt in the mapping
            # as well as on ``.receipt``.  The product envelope owns that
            # field; do not leak a duplicate receipt into DomainResult.data.
            data.pop("receipt", None)
            return {"data": plain(data), "receipt": plain(value.receipt)}
        return plain(value)

